/* the image with the 750 family's model code; the caller sets the code */
void cfg_defaults_750(unsigned char *img)
{
    size_t i;

    memset(img, 0xff, 0x4000);
    for (i = 0; i < sizeof runs / sizeof runs[0]; i++) memcpy(img + runs[i].off, runs[i].b, (size_t)runs[i].len);
}
